export function authLapse(data) {
  var _this = this;
  return new Promise(function (resolve, reject) {
    _this.$Notice.warning({
      title: data.title,
      duration: 3,
      desc: data.info,
      render: function render(h) {
        return h('div', [h('a', {
          attrs: {
            href: 'http://www.crmeb.com'
          }
        }, data.info)]);
      }
    });
    // if(data.status === false){
